<script setup>
import { computed, inject, onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { authorizedRequest } from './auth.js'
import RefreshIcon from './RefreshIcon.vue'
import DirectoryTree from './DirectoryTree.vue'

const can = inject('canPermission', () => false)
const directories = ref([]), entries = ref([]), selected = ref(0), search = ref(''), query = ref(''), error = ref(''), page = ref(1), pageSize = ref(10), total = ref(0)
const dialog = ref(false), viewing = ref(false), editing = ref(null), form = ref({}), importOpen = ref(false), importFile = ref(null), importResult = ref(null), busy = ref(false)
const treeRevision=ref(0)
async function sortDirectories(items){try{await saveRequest('/api/dictionary/directories/sort','POST',{items});await load()}catch(e){await load();error.value=e.message}finally{treeRevision.value++}}
function selectDirectory(id){selected.value=id;page.value=1;loadEntries()}
function directoryAction(action,node){if(action==='add')addDirectory(node);else if(action==='rename')renameDirectory(node);else if(action==='delete')removeDirectory(node)}
const types = ['varchar','char','integer','bigint','decimal','double','date','datetime','boolean']
const directoryOptions = computed(() => { const walk = (parent, depth) => directories.value.filter(d => d.parentId === parent).flatMap(d => [{ id:d.id, label:'　'.repeat(depth)+d.name }, ...walk(d.id,depth+1)]); return walk(null,0) })
function applyQuery() { query.value = search.value.trim(); page.value = 1; void loadEntries() }
async function request(url, options = {}) { const response = options.method ? await authorizedRequest(url, options) : await fetch(url,{credentials:'same-origin'}); if(!response.ok) { const data = await response.json().catch(() => null); throw new Error(data?.error || '操作失败，请检查权限和输入') } const text = await response.text(); return text ? JSON.parse(text) : null }
let loadSequence=0
async function loadEntries() { const sequence=++loadSequence; try { const params=new URLSearchParams({search:query.value,page:String(page.value),size:String(pageSize.value)});if(selected.value)params.set('directoryId',String(selected.value));const result=await request(`/api/dictionary/entries?${params}`);if(sequence!==loadSequence)return;if(page.value>1 && !result.rows.length && result.total>0){page.value=Math.ceil(result.total/pageSize.value);return loadEntries()}entries.value=result.rows;total.value=result.total } catch(e) { if(sequence===loadSequence)error.value=e.message } }
async function load() { try { error.value='';directories.value=await request('/api/dictionary/directories');await loadEntries() } catch(e) { error.value=e.message } }
async function saveRequest(url, method, body) { const response = await authorizedRequest(url,{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}); if(!response.ok) { const data=await response.json().catch(()=>null); throw new Error(data?.error || '操作失败') } }
async function addDirectory(node) { try { const result=await ElMessageBox.prompt('请输入目录名称','新增目录',{inputPattern:/\S/,inputErrorMessage:'请输入目录名称'}); await saveRequest('/api/dictionary/directories','POST',{name:result.value,parentId:node.id||null}); await load(); ElMessage.success('目录已新增') } catch(e) { if(e instanceof Error) error.value=e.message } }
async function renameDirectory(node) { try { const result=await ElMessageBox.prompt('请输入目录名称','修改目录',{inputValue:node.name,inputPattern:/\S/,inputErrorMessage:'请输入目录名称'}); await saveRequest(`/api/dictionary/directories/${node.id}`,'PUT',{name:result.value}); await load(); ElMessage.success('目录已修改') } catch(e) { if(e instanceof Error) error.value=e.message } }
async function removeDirectory(node) { try { await ElMessageBox.confirm(`确定删除目录「${node.name}」？`,'删除目录',{type:'warning'}); await request(`/api/dictionary/directories/${node.id}`,{method:'DELETE'}); if(selected.value===node.id)selected.value=0; await load(); ElMessage.success('目录已删除') } catch(e) { if(e instanceof Error) error.value=e.message } }
function openEntry(row, readOnly=false) { editing.value=row?.id ?? null; viewing.value=readOnly; form.value=row?{...row}:{directoryId:selected.value||null,code:'',name:'',meaning:'',dataType:'varchar',length:null,precision:null,description:''}; dialog.value=true }
async function saveEntry() { try { busy.value=true; const payload={...form.value,precision:['decimal','double'].includes(form.value.dataType)?form.value.precision:null}; await saveRequest(editing.value?`/api/dictionary/entries/${editing.value}`:'/api/dictionary/entries',editing.value?'PUT':'POST',payload); dialog.value=false; await load(); ElMessage.success('字典已保存') } catch(e) { ElMessage.error(e.message) } finally { busy.value=false } }
async function removeEntry(row) { try { await ElMessageBox.confirm(`确定删除字典「${row.name}」？`,'删除字典',{type:'warning'}); await request(`/api/dictionary/entries/${row.id}`,{method:'DELETE'}); await load(); ElMessage.success('字典已删除') } catch(e) { if(e instanceof Error) error.value=e.message } }
async function importEntries() { if(!importFile.value){ElMessage.warning('请选择文件');return} try { busy.value=true;const body=new FormData();body.append('file',importFile.value);importResult.value=await request('/api/dictionary/import',{method:'POST',body});await load() } catch(e){ElMessage.error(e.message)} finally{busy.value=false} }
onMounted(load)
</script>
<template><section class="dictionary-page"><el-alert v-if="error" :title="error" type="error" show-icon closable @close="error=''"/><div class="dictionary-layout"><DirectoryTree :key="treeRevision" :directories="directories" root-label="字典目录" :selected="selected" :can-create="can('datasource.dictionary.create')" :can-update="can('datasource.dictionary.update')" :can-delete="can('datasource.dictionary.delete')" @select="selectDirectory" @action="directoryAction" @sort="sortDirectories"/><div class="dictionary-main"><div class="toolbar list-query-toolbar"><div class="list-query-controls"><el-input v-model="search" placeholder="搜索字典标识、名称或含义" clearable @keyup.enter="applyQuery"/><el-button type="primary" @click="applyQuery">查询</el-button></div><div class="list-query-actions"><el-button v-if="can('datasource.dictionary.create')" type="primary" @click="openEntry(null)">新增</el-button><el-button v-if="can('datasource.dictionary.import')" @click="importResult=null; importFile=null; importOpen=true">导入</el-button><el-button class="refresh-button" title="刷新" aria-label="刷新" @click="load"><RefreshIcon/></el-button></div></div><div class="dictionary-list"><el-table :data="entries" height="100%" empty-text="暂无数据字典"><el-table-column type="index" label="序号" width="70"/><el-table-column prop="code" label="字典标识" min-width="140"/><el-table-column prop="name" label="字典名" min-width="120"/><el-table-column prop="meaning" label="字典含义" min-width="150"/><el-table-column prop="dataType" label="类型" width="100"/><el-table-column prop="length" label="长度" width="80"/><el-table-column label="操作" width="180" fixed="right"><template #default="scope"><el-button link type="primary" @click="openEntry(scope.row,true)">查看</el-button><el-button v-if="can('datasource.dictionary.update')" link type="primary" @click="openEntry(scope.row)">编辑</el-button><el-button v-if="can('datasource.dictionary.delete')" link type="danger" @click="removeEntry(scope.row)">删除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :total="total" @current-change="loadEntries" @size-change="page=1; loadEntries()" :page-sizes="[10,20,50]" layout="total, sizes, prev, pager, next"/></div></div></div>
<el-dialog v-model="dialog" :title="viewing?'查看字典':editing?'编辑字典':'新增字典'" width="min(700px,95vw)"><el-form label-position="top" :model="form"><div class="form-grid"><el-form-item label="字典目录" required><el-select v-model="form.directoryId" :disabled="viewing"><el-option v-for="d in directoryOptions" :key="d.id" :label="d.label" :value="d.id"/></el-select></el-form-item><el-form-item label="字典标识" required><el-input v-model="form.code" :disabled="viewing || !!editing" maxlength="100"/></el-form-item><el-form-item label="字典名" required><el-input v-model="form.name" :disabled="viewing" maxlength="200"/></el-form-item><el-form-item label="字典含义" required><el-input v-model="form.meaning" :disabled="viewing" maxlength="200"/></el-form-item><el-form-item label="字典类型" required><el-select v-model="form.dataType" :disabled="viewing"><el-option v-for="t in types" :key="t" :label="t" :value="t"/></el-select></el-form-item><el-form-item label="字典长度"><el-input-number v-model="form.length" :min="1" :disabled="viewing"/></el-form-item><el-form-item v-if="['decimal','double'].includes(form.dataType)" label="字典精度"><el-input-number v-model="form.precision" :min="0" :disabled="viewing"/></el-form-item></div><el-form-item label="描述"><el-input v-model="form.description" type="textarea" maxlength="1000" :disabled="viewing"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">关闭</el-button><el-button v-if="!viewing" type="primary" :loading="busy" @click="saveEntry">保存</el-button></template></el-dialog>
<el-dialog v-model="importOpen" title="导入数据字典" width="min(600px,95vw)"><p>支持 .xlsx 文件，最大 5 MB，最多 5000 行。目录路径须已存在，重复标识将跳过。</p><p>请在模板的“数据字典”工作表填写；“填写说明与示例”工作表介绍各字段和类型，不会被导入。</p><a href="/api/dictionary/template">下载导入模板</a><p><input type="file" accept=".xlsx" @change="importFile=$event.target.files[0]"/></p><div v-if="importResult"><p>成功 {{ importResult.success }} 条，失败 {{ importResult.failed }} 条</p><el-table v-if="importResult.errors.length" :data="importResult.errors" max-height="240"><el-table-column prop="row" label="行号" width="80"/><el-table-column prop="reason" label="原因"/></el-table></div><template #footer><el-button @click="importOpen=false">关闭</el-button><el-button type="primary" :loading="busy" @click="importEntries">导入</el-button></template></el-dialog></section></template>
<style scoped>.dictionary-page{height:100%;display:flex;flex-direction:column;min-height:0}.dictionary-layout{display:flex;gap:14px;flex:1;min-height:0}.dictionary-main{flex:1;min-width:0;min-height:0;display:flex;flex-direction:column}.dictionary-list{display:flex;flex-direction:column;flex:1;min-height:0;background:white}.dictionary-list .el-pagination{flex:none;padding:12px;justify-content:flex-end}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 18px}.form-grid .el-select{width:100%}@media(max-width:700px){.dictionary-layout{flex-direction:column}.form-grid{grid-template-columns:1fr}}</style>
